<?php require_once __DIR__.'/includes/bootstrap.php';require_login('request a certificate');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: official-documents.php');exit;}check_csrf();$type=trim($_POST['cert_type']??'');$purpose=trim($_POST['purpose']??'');if($type===''||$purpose===''){header('Location: official-documents.php?error=required');exit;}$ref=ref_code('CERT');$pdo->exec('CREATE TABLE IF NOT EXISTS certificate_requests(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,cert_type VARCHAR(100) NOT NULL,purpose VARCHAR(255) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT "pending",reference_code VARCHAR(40) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)');$s=$pdo->prepare('INSERT INTO certificate_requests(user_id,cert_type,purpose,status,reference_code) VALUES(?,?,?,?,?)');$s->execute([(int)$_SESSION['user']['id'],$type,$purpose,'pending',$ref]);header('Location: official-documents.php?reference='.rawurlencode($ref));exit;
